123	// Painel de pedidos do Bar/Copa — mesmo padrão de acesso da tela de Cozinha (dono já
124	// logado, sem link/token separado), lista PLANA de itens por setor de impressora (não
125	// agrupa por mesa/comanda — cada prato tem seu próprio ritmo e ação). Coexiste com
126	// /restaurante/producao (visão unificada de todos os setores) — essa aqui é só o Bar.
127	const RestauranteBar = () => {
128	  const navigate = useNavigate();
129	  const [impressorasBar, setImpressorasBar] = useState(null);
130	  const [itens, setItens] = useState([]);
131	  const [restauranteNome, setRestauranteNome] = useState('');
132	  const [loading, setLoading] = useState(true);
133	  const [erro, setErro] = useState(null);
134	  const [lastUpdate, setLastUpdate] = useState(null);
135	  const [filtroCanal, setFiltroCanal] = useState('todos'); // 'todos' | 'delivery' | 'salao'
136	  const now = useNowTick();
137	  const prevItemIds = useRef(new Set());
138	  const firstLoad = useRef(true);
139	  const tocarSom = useNotificacaoSonora('cozinha');
140	
141	  useEffect(() => {
142	    getMinhaEmpresa().then((d) => setRestauranteNome(d.empresa?.name ?? '')).catch(() => {});
143	    listarImpressoras()
144	      .then((lista) => setImpressorasBar((lista ?? []).filter((i) => (i.setor ?? '').toLowerCase().includes('bar'))))
145	      .catch((e) => setErro(e.message));
146	  }, []);
147	
148	  const carregar = useCallback(async (impressoras) => {
149	    try {
150	      const listas = await Promise.all(
151	        impressoras.map((imp) => getKdsItensRestaurante(imp.id).then((r) => r.itens ?? [])),
152	      );
153	      const todosItens = listas.flat().sort((a, b) => new Date(a.enviado_em).getTime() - new Date(b.enviado_em).getTime());
154	
155	      const idsAgora = new Set(todosItens.map((i) => i.id));
156	      if (!firstLoad.current) {
157	        const novos = [...idsAgora].filter((id) => !prevItemIds.current.has(id));
158	        if (novos.length > 0) tocarSom();
159	      } else {
160	        firstLoad.current = false;
161	      }
162	      prevItemIds.current = idsAgora;
163	
164	      setItens(todosItens);
165	      setLastUpdate(new Date());
166	      setErro(null);
167	    } catch (e) {
168	      setErro(e.message);
169	    } finally {
170	      setLoading(false);
171	    }
172	  }, [tocarSom]);
173	
174	  useEffect(() => {
175	    if (!impressorasBar) return;
176	    if (impressorasBar.length === 0) { setLoading(false); return; }
177	    carregar(impressorasBar);
178	    const interval = setInterval(() => carregar(impressorasBar), 15000);
179	    return () => clearInterval(interval);
180	  }, [impressorasBar, carregar]);
181	
182	  const marcarPronto = async (itemId) => {
183	    await marcarItemProntoRestaurante(itemId);
184	    carregar(impressorasBar);
185	  };
186	
187	  const iniciarPreparo = async (item) => {
188	    await iniciarPreparoItemRestaurante(item.id);
189	    carregar(impressorasBar);
190	  };
191	
192	  const voltar = async (item) => {
193	    try {
194	      await voltarStatusItemRestaurante(item.id);
195	      carregar(impressorasBar);
196	    } catch (e) {
197	      setErro(e.message);
198	    }
199	  };
200	
201	  const reimprimir = async (item) => {
202	    try {
203	      const res = await reimprimirItemRestaurante(item.id);
204	      if (res.via === 'navegador') {
205	        printTicketSetor([item], { mesaLabel: item.mesa, cliente_mesa_nome: item.cliente }, 'Bar');
206	      }
207	    } catch (e) {
208	      setErro(e.message);
209	    }
210	  };
211	
212	  if (loading) return (
213	    <div className="min-h-screen bg-[#111111] flex items-center justify-center">
214	      <div className="w-10 h-10 border-4 border-[#FF441F] border-t-transparent rounded-full animate-spin" />
215	    </div>
216	  );
217	
218	  const itensFiltrados = itens.filter((i) => filtroCanal === 'todos' || i.tipo === filtroCanal);
219	  const aguardando = itensFiltrados.filter((i) => i.status === 'enviado');
220	  const preparando = itensFiltrados.filter((i) => i.status === 'preparando');
221	  const prontosRecentes = itensFiltrados.filter((i) => i.status === 'pronto');
222	  const totalDelivery = itens.filter((i) => i.tipo === 'delivery').length;
223	  const totalSalao = itens.filter((i) => i.tipo === 'salao').length;
224	
225	  return (
226	    <div className="min-h-screen bg-[#111111]">
227	      <header className="bg-[#1A1A1A] border-b border-[#2A2A2A] px-5 py-3">
228	        <div className="flex items-center gap-4">
229	          <button onClick={() => navigate('/restaurante')} className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
230	            <Icon name="ArrowLeft" size={18} />
231	          </button>
232	          <div className="flex items-center gap-2">
233	            <div className="w-8 h-8 bg-[#FF441F] rounded-lg flex items-center justify-center flex-shrink-0">
234	              <Icon name="Martini" size={16} className="text-white" />
235	            </div>
236	            <div>
237	              <p className="text-white font-black text-base leading-none">Painel do Bar</p>
238	              <p className="text-[#71717A] text-xs">{restauranteNome}</p>
239	            </div>
240	          </div>
241	          <div className="ml-auto flex items-center gap-2">
242	            <div className="flex items-center gap-2 text-xs text-[#71717A]">
243	              <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse" />
244	              {lastUpdate?.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) ?? '—'}
245	            </div>
246	            <button onClick={() => carregar(impressorasBar ?? [])} className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
247	              <Icon name="RefreshCw" size={16} />
248	            </button>
249	          </div>
250	        </div>
251	
252	        {/* Filtro de canal — Todos/Delivery/Salão */}
253	        <div className="flex items-center gap-2 mt-3">
254	          {[
255	            { key: 'todos', label: 'Todos', count: totalDelivery + totalSalao },
256	            { key: 'delivery', label: 'Delivery', count: totalDelivery },
257	            { key: 'salao', label: 'Salão', count: totalSalao },
258	          ].map((f) => (
259	            <button
260	              key={f.key}
261	              onClick={() => setFiltroCanal(f.key)}
262	              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ${
263	                filtroCanal === f.key
264	                  ? 'bg-[#FF441F] text-white'
265	                  : 'bg-[#111111] text-[#71717A] border border-[#2A2A2A] hover:text-white'
266	              }`}
267	            >
268	              {f.label}
269	              <span className={`px-1.5 py-0.5 rounded-full text-[10px] ${filtroCanal === f.key ? 'bg-white/20' : 'bg-[#2A2A2A]'}`}>{f.count}</span>
270	            </button>
271	          ))}
272	        </div>
273	      </header>
274	
275	      {erro && (
276	        <div className="mx-5 mt-4 bg-red-900/50 border border-red-700 rounded-xl px-4 py-3 text-sm text-red-400">{erro}</div>
277	      )}
278	
279	      {impressorasBar && impressorasBar.length === 0 ? (
280	        <div className="text-center py-20 px-5">
281	          <Icon name="Printer" size={48} className="text-[#2A2A2A] mx-auto mb-4" />
282	          <p className="text-[#71717A] text-lg font-semibold">Nenhuma impressora de setor "Bar" cadastrada</p>
283	          <p className="text-[#3A3A3A] text-sm mt-1">Cadastre uma impressora com o setor "Bar" na tela de Impressoras.</p>
284	          <button onClick={() => navigate('/restaurante/impressoras')}
285	            className="mt-4 px-4 py-2 bg-[#FF441F] text-white text-sm font-bold rounded-xl hover:bg-[#E63A19]">
286	            Ir pra Impressoras
287	          </button>
288	        </div>
289	      ) : (
290	        <main className="p-5 grid grid-cols-1 lg:grid-cols-2 gap-6 max-w-5xl mx-auto">
291	          <div>
292	            <div className="flex items-center gap-2 mb-3">
293	              <div className="w-3 h-3 rounded-full bg-blue-400" />
294	              <h2 className="text-white font-bold text-sm uppercase tracking-wider">Aguardando Motoboy</h2>
295	              {aguardando.length > 0 && (
296	                <span className="ml-auto bg-blue-500 text-white text-xs font-black px-2 py-0.5 rounded-full">{aguardando.length}</span>
297	              )}
298	            </div>
299	            {aguardando.length === 0 ? (
300	              <div className="rounded-2xl border-2 border-dashed border-[#2A2A2A] p-8 text-center">
301	                <Icon name="CheckCircle" size={32} className="text-[#3A3A3A] mx-auto mb-2" />
302	                <p className="text-[#71717A] text-sm">Nenhum pedido aguardando</p>
